document.getElementById('btnReset').style.display = '';

const clampN=(v,a,b)=>Math.max(a,Math.min(b,v));
function lossAt(p0,p1){const a=p0-1.45,b=p1-0.25;return 12*a*a+14*a*b+10*b*b;}
function gradAt(p0,p1){const a=p0-1.45,b=p1-0.25;return [24*a+14*b,14*a+20*b];}
function yAt(p0,p1){return Math.min(lossAt(p0,p1),70)/70*3;}

/* ── shared colormap (L = 0 .. 70) ─────────────────────────────────────── */
const CSTOPS=[[0.00,[46,16,13]],[0.12,[59,21,18]],[0.42,[122,58,42]],
              [0.68,[185,112,63]],[0.90,[242,224,188]],[1.00,[253,246,224]]];
function cmap(t){
  t=clampN(t,0,1);
  for(let i=0;i<CSTOPS.length-1;i++){
    const A=CSTOPS[i],B=CSTOPS[i+1];
    if(t<=B[0]){
      const u=(t-A[0])/(B[0]-A[0]||1);
      return [A[1][0]+(B[1][0]-A[1][0])*u,A[1][1]+(B[1][1]-A[1][1])*u,A[1][2]+(B[1][2]-A[1][2])*u];
    }
