  {c:'#c9d2d0',p0:1.60,p1:-0.78,n:'Pale point'},
  {c:'#96e0d8',p0:0.40,p1: 0.25,n:'Light cyan point'},
  {c:'#2f8b82',p0:0.90,p1: 0.50,n:'Teal point'}
