MARKERS.forEach(m=>{
  const s=new THREE.Mesh(new THREE.SphereGeometry(0.09,20,14),new THREE.MeshBasicMaterial({color:m.c}));
  s.position.set(2*m.p0-2,yAt(m.p0,m.p1)+0.055,2*m.p1);
  groupA.add(s);
  const info={title:m.n+'  (φ₀='+m.p0.toFixed(2)+', φ₁='+m.p1.toFixed(2)+')',
    tooltip:'L = '+lossAt(m.p0,m.p1).toFixed(1),
    body:'This parameter setting has loss L[φ] = '+lossAt(m.p0,m.p1).toFixed(2)+
         '. The same point appears in panel a) on the surface and in panel b) on the contour map.'};
  registerInteractive(s,info);
  const ring=new THREE.Mesh(new THREE.RingGeometry(0.10,0.125,28),
    new THREE.MeshBasicMaterial({color:0xffffff}));
  ring.position.set(2*m.p0-2,-2*m.p1,0.010);
  const disc=new THREE.Mesh(new THREE.CircleGeometry(0.10,28),
    new THREE.MeshBasicMaterial({color:m.c}));
  disc.position.set(2*m.p0-2,-2*m.p1,0.012);
  groupB.add(ring,disc);registerInteractive(disc,info);
});

/* ── current (interactive) marker ──────────────────────────────────────── */
const GOLD=0xffb300;
const goldMat=()=>new THREE.MeshBasicMaterial({color:GOLD});
const dotA=new THREE.Mesh(new THREE.SphereGeometry(0.05,14,10),goldMat());
const pinA=new THREE.Mesh(new THREE.SphereGeometry(0.095,20,14),goldMat());
