/* ── descent path objects ──────────────────────────────────────────────── */
const MAXIT=170;
function makePath(){
  const arr=new Float32Array(MAXIT*3);
  const geo=new THREE.BufferGeometry();
  geo.setAttribute('position',new THREE.BufferAttribute(arr,3));
  geo.setDrawRange(0,0);
  const line=new THREE.Line(geo,new THREE.LineBasicMaterial({color:0xffd27f}));
  const pts=new THREE.Points(geo,new THREE.PointsMaterial({color:0xffffff,size:4.5,sizeAttenuation:false}));
  line.frustumCulled=false;pts.frustumCulled=false;
  return {geo,arr,line,pts};
}
const pathA=makePath(),pathB=makePath();
groupA.add(pathA.line,pathA.pts);
groupB.add(pathB.line,pathB.pts);

