const MULT={a:1,b:0.82,both:1.55};
function applyLabelStyle(){
  const m=MULT[state.view];
  ALLL.forEach(e=>{
    const vis=(state.view==='both')||(e.panel===state.view);
    e.div.style.visibility=vis?'visible':'hidden';
    e.div.style.fontSize=(e.base*m)+'px';
  });
}
function billboardB(){
  groupB.quaternion.copy(camera.quaternion);
  groupB.updateMatrixWorld(true);
  for(const o of BLBL) o.e.pos.copy(o.l).applyMatrix4(groupB.matrixWorld);
