/* ── state & UI wiring ─────────────────────────────────────────────────── */
const state={view:'a',phi0:1.45,phi1:0.25,lr:0.02,desc:'idle'};
const $=id=>document.getElementById(id);
const s0=$('s0'),s1=$('s1'),slr=$('slr');

function nearStatic(p0,p1){
  return MARKERS.some(m=>Math.hypot(m.p0-p0,m.p1-p1)<0.10);
}
function updateMarkers(){
  const p0=state.phi0,p1=state.phi1;
  const x=2*p0-2,z=2*p1,y=yAt(p0,p1);
  const hide=nearStatic(p0,p1);          // never cover one of the three source dots
  dotA.visible=!hide; curDotB.visible=!hide;
  dotA.position.set(x,y+0.03,z);
  pinA.position.set(x,y+0.55,z);
  grabA.position.set(x,y+0.55,z);
  const pa=stemGeo.attributes.position;
  pa.setXYZ(0,x,y+(hide?0.17:0.03),z);pa.setXYZ(1,x,y+0.53,z);pa.needsUpdate=true;
  curRingB.position.set(x,-z,0.02);
  curDotB.position.set(x,-z,0.022);
  grabB.position.set(x,-z,0.03);
  lblCur.pos.set(x,y+0.85,z);
  const Lv=lossAt(p0,p1);
  lblCur.div.innerHTML='L = '+Lv.toFixed(1);
  $('v0').textContent=p0.toFixed(2);
  $('v1').textContent=p1.toFixed(2);
  $('readout').textContent='φ₀ = '+p0.toFixed(2)+'   φ₁ = '+p1.toFixed(2)+'   L = '+Lv.toFixed(2);
}
function setPhi(p0,p1,silent){
  state.phi0=clampN(p0,0,2);state.phi1=clampN(p1,-1,1);
  s0.value=state.phi0;s1.value=state.phi1;
  updateMarkers();
  if(!silent) stopDescent();
}
function setView(v){
  state.view=v;
  ['a','b','both'].forEach(k=>{
    $(k==='a'?'viewA':k==='b'?'viewB':'viewBoth').classList.toggle('active',k===v);
  });
  if(v==='a'){ if(groupB.parent) scene.remove(groupB); if(!groupA.parent) scene.add(groupA); }
  else if(v==='b'){ if(groupA.parent) scene.remove(groupA); if(!groupB.parent) scene.add(groupB); }
  else { if(!groupA.parent) scene.add(groupA); if(!groupB.parent) scene.add(groupB); }
  applyLabelStyle();
  billboardB();
  setCameraView(VIEWS[v]);
  billboardB();
}
$('viewA').onclick=()=>setView('a');
$('viewB').onclick=()=>setView('b');
$('viewBoth').onclick=()=>setView('both');
s0.oninput=()=>setPhi(parseFloat(s0.value),state.phi1);
s1.oninput=()=>setPhi(state.phi0,parseFloat(s1.value));
slr.oninput=()=>{state.lr=parseFloat(slr.value);$('vlr').textContent=state.lr.toFixed(3);};

/* ── gradient descent ──────────────────────────────────────────────────── */
let pathPts=[],anim={active:false,t:0,shown:0},pathOutcome='idle';
function setDescState(s,extra){
  state.desc=s;
  $('descState').innerHTML='Gradient descent: <b>'+s+'</b>'+(extra?' <span style="color:#a33">'+extra+'</span>':'');
}
function writePath(){
  for(let i=0;i<MAXIT;i++){
    const p=pathPts[Math.min(i,pathPts.length-1)]||[state.phi0,state.phi1];
    const x=2*p[0]-2,z=2*p[1];
    pathA.arr[i*3]=x;pathA.arr[i*3+1]=yAt(p[0],p[1])+0.06;pathA.arr[i*3+2]=z;
    pathB.arr[i*3]=x;pathB.arr[i*3+1]=-z;pathB.arr[i*3+2]=0.05;
  }
  pathA.geo.attributes.position.needsUpdate=true;
  pathB.geo.attributes.position.needsUpdate=true;
}
function drawN(n){pathA.geo.setDrawRange(0,n);pathB.geo.setDrawRange(0,n);}
function computePath(p0,p1,al){
  const pts=[[p0,p1]];pathOutcome='converged';
  for(let i=0;i<MAXIT-1;i++){
    const last=pts[pts.length-1];
    const g=gradAt(last[0],last[1]);
    if(Math.hypot(g[0],g[1])<1e-3) break;
    const n0=last[0]-al*g[0],n1=last[1]-al*g[1];
    if(n0<-0.3||n0>2.3||n1<-1.3||n1>1.3){
      pts.push([clampN(n0,-0.3,2.3),clampN(n1,-1.3,1.3)]);
      pathOutcome='diverged';break;
    }
    pts.push([n0,n1]);
  }
  return pts;
}
function runDescent(){
  pathPts=computePath(state.phi0,state.phi1,state.lr);
  writePath();drawN(1);
  anim={active:true,t:0,shown:1};
  setDescState('running');
}
function stopDescent(){
  anim.active=false;
  if(state.desc!=='idle') setDescState('idle');
  pathPts=[];drawN(0);
}
$('btnRun').onclick=runDescent;
$('btnResetPath').onclick=stopDescent;

let lastT=performance.now();
function tickLocal(){
  requestAnimationFrame(tickLocal);
  const now=performance.now(),dt=now-lastT;lastT=now;
  if(groupB.parent) billboardB();
  if(anim.active){
    anim.t+=dt;
    const n=Math.min(pathPts.length,Math.floor(anim.t/130)+1);
    if(n!==anim.shown){
      anim.shown=n;drawN(n);
      setPhi(pathPts[n-1][0],pathPts[n-1][1],true);
    }
    if(n>=pathPts.length){
      anim.active=false;
      setDescState(pathOutcome==='converged'?'converged':'diverged',
        pathOutcome==='converged'?'— L = '+lossAt(state.phi0,state.phi1).toFixed(3)
                                 :'— α above 2/λ_max, iterates blow up');
    }
  }
}
tickLocal();

/* ── drag / click to set parameters ────────────────────────────────────── */
const _ray=new THREE.Raycaster(),_ndc=new THREE.Vector2();
const _flat=new THREE.Plane(new THREE.Vector3(0,1,0),0);
let dragging=false,downX=0,downY=0,movedPx=0;
function setRay(ev){
  const r=canvas.getBoundingClientRect();
  _ndc.x=((ev.clientX-r.left)/r.width)*2-1;
  _ndc.y=-((ev.clientY-r.top)/r.height)*2+1;
  _ray.setFromCamera(_ndc,camera);
}
function pickPhi(ev){
  setRay(ev);
  const cand=[];
  if(groupB.parent) cand.push(mapMesh);
  if(groupA.parent) cand.push(surfMesh);
  const h=_ray.intersectObjects(cand,false);
  if(h.length){
    const p=h[0].point;
    if(h[0].object===mapMesh){
      groupB.updateMatrixWorld(true);
      const l=groupB.worldToLocal(p.clone());
      return [clampN((l.x+2)/2,0,2),clampN(-l.y/2,-1,1)];
    }
    return [clampN((p.x+2)/2,0,2),clampN(p.z/2,-1,1)];
  }
  if(groupA.parent){
    const t=new THREE.Vector3();
    if(_ray.ray.intersectPlane(_flat,t)&&Math.abs(t.x)<2.6&&Math.abs(t.z)<2.6)
      return [clampN((t.x+2)/2,0,2),clampN(t.z/2,-1,1)];
  }
  return null;
}
canvas.addEventListener('pointerdown',(e)=>{
  downX=e.clientX;downY=e.clientY;movedPx=0;
  setRay(e);
  const handles=[];
  if(groupA.parent) handles.push(grabA,pinA);
  if(groupB.parent) handles.push(grabB);
  if(handles.length&&_ray.intersectObjects(handles,false).length){
    dragging=true;controls.enabled=false;anim.active=false;
  }
},true);
canvas.addEventListener('pointermove',(e)=>{
  movedPx=Math.abs(e.clientX-downX)+Math.abs(e.clientY-downY);
  if(!dragging) return;
  const p=pickPhi(e);if(p) setPhi(p[0],p[1]);
});
window.addEventListener('pointerup',(e)=>{
  if(dragging){dragging=false;controls.enabled=true;return;}
  if(movedPx<5&&e.target===canvas){const p=pickPhi(e);if(p) setPhi(p[0],p[1]);}
});

