let stepI=0;
function goToStep(i){
  stepI=(i+STEPS.length)%STEPS.length;
  const st=STEPS[stepI];
  stopDescent();
  setView(st.s.view);
  if(st.s.lr!==undefined){state.lr=st.s.lr;slr.value=st.s.lr;$('vlr').textContent=st.s.lr.toFixed(3);}
  setPhi(st.s.phi0,st.s.phi1,true);
  $('stepTitle').textContent=st.t;
  $('stepNarr').textContent=st.n;
  $('stepIdx').textContent='step '+(stepI+1)+' / '+STEPS.length;
  if(st.s.run) runDescent(); else setDescState('idle');
}
$('btnPrev').onclick=()=>goToStep(stepI-1);
$('btnNext').onclick=()=>goToStep(stepI+1);

